"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Mikä tahansa huone: kotiin tuodut tarvikkeet +{0} %. Sopivuus ”Onni”: tarvikkeet +{1} % lisää, aloituspistekerroin +{2} joka taistelussa.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Mikä tahansa huone: retken näkyvyys +{0}, aloituspistekerroin +{1}. Sopivuus ”Onni / Erikois”: retkikartta on alusta asti täysin näkyvissä, kerroin +{2} lisää.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Mikä tahansa huone: retkijoukkojen hyökkäys +{0} %. Sopivuus ”Koulutus”: johtajan retki-KP +{1} %.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Mikä tahansa huone: retkijoukkojen HP +{0} %. Sopivuus ”Lääkintä”: sairaalan parannus +{1} %, johtaja paranee {2} % lisää päivässä.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Mikä tahansa huone: piirustusten pudotus +{0} %. Sopivuus ”Scifi”: tukikohta: Sielunsirpaleet +{1} päivässä.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Mikä tahansa huone: piirustusten pudotus +{0} %. Sopivuus ”Takominen”: takoessa {1} % mahdollisuus ylimääräiseen reliikkiin.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Mikä tahansa huone: tukikohta: Sielunsirpaleet +{0} päivässä. Sopivuus ”Taika”: +{1} lisää päivässä.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Mikä tahansa huone: tukikohta: Tarvikkeet +{0} päivässä. Sopivuus ”Logistiikka”: tämän huoneen oma vaikutus ×{1}.",
