"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Mikä tahansa huone: reliikkien takomisen hinta -{0} %. Sopivuus ”Takominen / Ase”: takomisessa {1} % mahdollisuus laatuun +{2}; aseiden vahinko +{3} %.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Mikä tahansa huone: rakennusaika puolittuu, valmistuessa {0} % tarvikkeista palautetaan. Sopivuus ”Ihme”: palautus {1} %.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Mikä tahansa huone: kaikkien puolustustornien vahinko +{0} %. Sopivuus ”Ase”: kantama +{1}, hyökkäysnopeus +{2} %.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Mikä tahansa huone: kaivamisen hinta -{0} %. Sopivuus ”Erikois”: kaikki rakentaminen -{1} pv.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Mikä tahansa huone: aloituspistekerroin +{0} joka taistelussa. Sopivuus ”Takominen”: taotut reliikit aina laatu +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Mikä tahansa huone: johtajan taidon lataus -{0} pys. Sopivuus ”Onni”: aloita retket +{1} tukiesineellä (vähintään ”Eeppinen” vaikutus).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Mikä tahansa huone: johtajan hyökkäys +{0} %. Sopivuus ”Ase”: vahinko +{1} %, jokainen hyökkäys laukaisee ketjusalaman (hyppää vihollisiin: {2}).",
