"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Mikä tahansa huone: johtaja saa KP +{0} päivässä. Sopivuus ”Tuotanto”: tämän huoneen oma tuotto ×{1}.",
